import urllib.request
import urllib.error
import time
from typing import Optional


class RateLimitError(Exception):
    """Raised when the API returns a 429 Too Many Requests."""
    pass


class ServerError(Exception):
    """Raised when the API returns a 5xx error after retry."""
    pass


class ClientError(Exception):
    """Raised when the API returns a 4xx error (except 429)."""
    pass


class ConnectionError(Exception):
    """Raised when a network error occurs after retry."""
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10) -> None:
        self.base_url = base_url
        self.timeout = timeout

    def _handle_response(self, response: urllib.request.HTTPResponse) -> str:
        status = response.status
        body = response.read().decode("utf-8")

        if status == 429:
            raise RateLimitError(f"Rate limited: {body}")
        if 500 <= status < 600:
            raise ServerError(f"Server error: {body}")
        if 400 <= status < 500:
            raise ClientError(f"Client error: {body}")
        return body

    def _retry_request(
        self,
        path: str,
        max_retries: int,
        backoff: list[float],
        error_class: type[Exception],
        retry_on_status: Optional[set[int]] = None,
    ) -> str:
        retry_on_status = retry_on_status or set()
        for attempt in range(max_retries):
            try:
                url = f"{self.base_url}{path}"
                req = urllib.request.Request(url, method="GET")
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    return self._handle_response(resp)
            except urllib.error.HTTPError as e:
                if e.code in retry_on_status:
                    if attempt < len(backoff):
                        time.sleep(backoff[attempt])
                        continue
                    raise error_class(f"HTTP {e.code} after retries: {e.reason}")
                raise error_class(f"HTTP {e.code}: {e.reason}")
            except urllib.error.URLError as e:
                if attempt < len(backoff):
                    time.sleep(backoff[attempt])
                    continue
                raise error_class(f"Network error: {e.reason}")

    def get(self, path: str) -> str:
        # 429: up to 3 retries with exponential backoff (0.5, 1, 2)
        # 5xx: 1 retry after 1s
        # 4xx (except 429): no retry
        # network errors: 1 retry after 1s
        return self._retry_request(
            path,
            max_retries=3,
            backoff=[0.5, 1.0, 2.0],
            error_class=RateLimitError,
            retry_on_status={429},
        )
